// 1. Sanitizar y parsear la salida del AI Agent
let raw = $input.first().json.output;
raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
const data = JSON.parse(raw);

const requests = [];
const put = (placeholder, value) => requests.push({
  replaceAllText: {
    containsText: { text: `{{${placeholder}}}`, matchCase: true },
    replaceText: String(value ?? "")
  }
});

// 2. Campos de encabezado
put('fecha_emision', data.fecha_emision);
put('numero_factura', data.numero_factura);
put('id_cliente', data.id_cliente);
put('nombre_cliente', data.nombre_cliente);
put('fecha_vencimiento', data.fecha_vencimiento);

// 3. Filas de detalle + cálculo de total por fila
const precioOficina = Number(data.precio_oficina) || 0;
const precioExtra = Number(data.precio_extra) || 0;

let subtotal = 0;
let horasTotales = 0;

for (let i = 1; i <= 7; i++) {
  const fila = data.filas?.[i - 1] || {};
  const horasOficina = Number(fila.horas_oficina) || 0;
  const horasExtra = Number(fila.horas_extra) || 0;
  const total = horasOficina * precioOficina + horasExtra * precioExtra;

  subtotal += total;
  horasTotales += horasOficina + horasExtra;

  put(`consultor_${i}`, fila.consultor ?? '');
  put(`detalle_trabajo_${i}`, fila.detalle_trabajo ?? '');
  put(`ticket_${i}`, fila.ticket ?? '');
  put(`horas_oficina_${i}`, horasOficina || '');
  put(`horas_extra_${i}`, horasExtra || '');
  put(`total_${i}`, total || '');
}

// 4. Totales generales
const impuesto = subtotal * 0.21;
const total = subtotal + impuesto;

put('subtotal', subtotal);
put('impuesto', impuesto);
put('total', total);

// 5. Excedente sobre el abono (no va en la factura, va en el mail al revisor)
const abonoMax = Number(data.abono_horas_maximas) || 0;
const excedente = Math.max(0, horasTotales - abonoMax);
const notaExcedente = excedente > 0
  ? `⚠️ Este cliente trabajó ${horasTotales}hs, ${excedente}hs por encima del abono contratado (${abonoMax}hs).`
  : '';

// 6. Salida: requests para el batchUpdate + datos sueltos para el nodo Gmail
return {
  requests,
  nombre_cliente: data.nombre_cliente,
  numero_factura: data.numero_factura,
  subtotal,
  impuesto,
  total,
  notaExcedente,
  advertencia: data.advertencia || '',
  sinHoras: !data.filas || data.filas.length === 0   // no hay horas para facturar
};

